{
  "schema_version": "2.0",
  "checklist_id": "FC-BEI-001",
  "record_id": "HG-BEI-001",
  "hypotheses": [
    {
      "hypothesis_id": "H1",
      "candidate_status": "candidate",
      "assumptions": [
        "The pilot report reflects a real difference in immune-function readouts, not pure measurement noise.",
        "The editor reaches and edits the intended cell population at detectable fractions."
      ],
      "boundary_conditions": [
        "Aged mice as piloted; preregistered readouts and locked horizon."
      ],
      "falsifier": {
        "prediction_id": "P1",
        "conditions": "Randomized three-arm replicate with blinded assessment and passing editing checks.",
        "observable": "Primary immune-function readout by arm at the locked horizon, with on-target editing fractions (P5).",
        "incompatible_result": "Delivery-only arm matches the full-editor arm, or restoration occurs without detectable on-target editing.",
        "assumption_failure_checks": [
          "Verify randomization, blinding, baseline coverage, and editing-assay sensitivity before interpreting incompatibility."
        ]
      },
      "discriminating_tests": [
        {
          "test_id": "DT1",
          "rival_hypothesis_id": "H2",
          "focal_expected": "Full-editor arm improves beyond delivery-only and inactive-editor arms and persists to the horizon.",
          "rival_expected": "Delivery-only arm improves similarly with an early transient that fades.",
          "indeterminate_result": "Both arms improve, so delivery and editing contributions remain mixed."
        },
        {
          "test_id": "DT2",
          "rival_hypothesis_id": "H5",
          "focal_expected": "Restoration tracks on-target editing fraction with minimal relevant off-target burden.",
          "rival_expected": "Restoration tracks off-target burden or DNA-damage signatures rather than on-target editing.",
          "indeterminate_result": "Both on-target and off-target edits present at interpretable fractions."
        }
      ],
      "nulls": [
        {
          "null_id": "N1",
          "statement": "Primary readout means are equal between the full-editor arm and the delivery-only arm at the locked horizon.",
          "analysis_id": "A1",
          "interpretation_limit": "Failure to reject is not equivalence, absence of effect, or proof of a rival."
        }
      ],
      "controls": [
        {
          "control_id": "NC1",
          "control_type": "negative_outcome",
          "rationale": "The catalytically-inactive editor or sham guide shares every delivery and bias pathway but cannot operate through the editing mechanism.",
          "expected_result": "No improvement beyond the delivery-only arm.",
          "failure_implication": "Investigate editor-package effects, contamination, or assignment bias before any causal interpretation."
        },
        {
          "control_id": "PC1",
          "control_type": "positive_control",
          "rationale": "A known-responsive sample (mitogen-stimulated or young-animal reference) verifies each assay detects a declared change.",
          "expected_result": "Reference response recovered within locked tolerance.",
          "failure_implication": "Affected readouts are not interpretable until assay performance is restored."
        }
      ],
      "outcome_interpretation": {
        "consistent_with_candidate": "Full-editor arm exceeds both controls at the horizon, tracks on-target editing fraction, and passes blinding, baseline, and platform checks.",
        "challenges_candidate": "Delivery-only arm matches the full-editor arm, or restoration lacks detectable on-target editing, while assumptions remain credible.",
        "supports_neither_or_mixed": "Both arms improve, patterns match no candidate, or an assumption or control fails."
      },
      "human_review_status": "pending"
    },
    {
      "hypothesis_id": "H2",
      "candidate_status": "candidate",
      "assumptions": [
        "Delivery-associated innate activation can shift the immune readouts used in the pilot."
      ],
      "boundary_conditions": [
        "Same arms and sampling times as the primary replicate."
      ],
      "falsifier": {
        "prediction_id": "P2",
        "conditions": "Prespecified time-course with locked sampling windows.",
        "observable": "Early cytokine and innate markers plus immune readouts over weeks, by arm.",
        "incompatible_result": "Delivery-only arm shows neither early transient nor improvement while the full-editor arm improves.",
        "assumption_failure_checks": [
          "Verify cytokine-assay sensitivity, sampling timing, and vehicle identity across arms."
        ]
      },
      "discriminating_tests": [
        {
          "test_id": "DT3",
          "rival_hypothesis_id": "H1",
          "focal_expected": "Early arm-shared transient that fades within weeks, mirroring delivery exposure.",
          "rival_expected": "No arm-shared transient; sustained change only where editing occurred.",
          "indeterminate_result": "Transient present plus late edit-bearing-arm change: both mechanisms may contribute."
        }
      ],
      "nulls": [
        {
          "null_id": "N2",
          "statement": "Early innate-marker means are equal between the delivery-only arm and the full-editor arm.",
          "analysis_id": "A2",
          "interpretation_limit": "Failure to reject does not show the vehicle is inert when precision or timing is insufficient."
        }
      ],
      "controls": [
        {
          "control_id": "NC1",
          "control_type": "negative_outcome",
          "rationale": "The inactive-editor arm isolates the editor package from delivery; the delivery-only arm carries the vehicle alone.",
          "expected_result": "An H2 explanation predicts arm-shared early changes that the editing-only contrast should not produce.",
          "failure_implication": "A delivery effect restricted to the vehicle arm challenges the vehicle-specific account."
        }
      ],
      "outcome_interpretation": {
        "consistent_with_candidate": "Arm-shared early transient with fading readout changes under valid timing and assay sensitivity.",
        "challenges_candidate": "No transient and no delivery-only improvement while the full-editor arm improves durably.",
        "supports_neither_or_mixed": "Timing confounded across arms, or both delivery and editing patterns occur."
      },
      "human_review_status": "pending"
    },
    {
      "hypothesis_id": "H3",
      "candidate_status": "candidate",
      "assumptions": [
        "Any artifact operates through gating, lot, instrument, batch, or analysis-pipeline pathways shared across the pilot's data flow."
      ],
      "boundary_conditions": [
        "Same primary readout as P1; independent platform calibrated before unblinding."
      ],
      "falsifier": {
        "prediction_id": "P3",
        "conditions": "Locked-gate blinded reanalysis plus an independent assay platform.",
        "observable": "Effect direction and magnitude across both analysis modes and platforms.",
        "incompatible_result": "Locked-gate blinded reanalysis and the independent platform both reproduce the effect.",
        "assumption_failure_checks": [
          "Verify gate-locking, blinding integrity, and platform calibration before interpreting incompatibility."
        ]
      },
      "discriminating_tests": [
        {
          "test_id": "DT4",
          "rival_hypothesis_id": "H1",
          "focal_expected": "Effect unstable under locked gates or discordant across platforms.",
          "rival_expected": "Effect robust across locked gates and concordant across platforms.",
          "indeterminate_result": "Platforms agree in direction but differ in magnitude."
        }
      ],
      "nulls": [
        {
          "null_id": "N3",
          "statement": "The primary readout effect size is unchanged between locked-gate and exploratory-gate analyses.",
          "analysis_id": "A3",
          "interpretation_limit": "Failure to reject does not prove measurement validity when platform precision is insufficient."
        }
      ],
      "controls": [
        {
          "control_id": "PC1",
          "control_type": "positive_control",
          "rationale": "A known-responsive reference verifies each platform detects a declared change.",
          "expected_result": "Reference recovered within locked tolerance on both platforms.",
          "failure_implication": "Artifact claims are uninterpretable until platform performance is established."
        }
      ],
      "outcome_interpretation": {
        "consistent_with_candidate": "Effect flips or fades under locked gates, or platforms disagree, under verified blinding and calibration.",
        "challenges_candidate": "Effect survives locked gates and concurs across both platforms.",
        "supports_neither_or_mixed": "Blinding or calibration fails, or only part of the effect is platform-dependent."
      },
      "human_review_status": "pending"
    },
    {
      "hypothesis_id": "H4",
      "candidate_status": "candidate",
      "assumptions": [
        "Baseline health and treatment tolerance covary in aged animals, creating a selection pathway from health to both treatment completion and immune readouts."
      ],
      "boundary_conditions": [
        "Requires pre-treatment measures on every animal and attrition recorded by arm."
      ],
      "falsifier": {
        "prediction_id": "P4",
        "conditions": "Paired within-animal analysis at the planned n, exclusions locked before unblinding.",
        "observable": "Baseline predictors of response, attrition symmetry, within-animal change.",
        "incompatible_result": "Baseline composition explains the effect, or the effect vanishes at planned n under paired analysis.",
        "assumption_failure_checks": [
          "Verify baseline coverage, attrition records, and exclusion-rule locking before interpreting incompatibility."
        ]
      },
      "discriminating_tests": [
        {
          "test_id": "DT5",
          "rival_hypothesis_id": "H1",
          "focal_expected": "Responders healthier at baseline; effect attenuates under paired analysis.",
          "rival_expected": "Within-animal improvement independent of baseline health; symmetric attrition.",
          "indeterminate_result": "Baseline differences exist but the adjusted effect persists."
        }
      ],
      "nulls": [
        {
          "null_id": "N4",
          "statement": "Within-animal change on the primary readout is equal between full-editor and delivery-only arms.",
          "analysis_id": "A4",
          "interpretation_limit": "Failure to reject is not equivalence; baseline adjustment is model-dependent."
        }
      ],
      "controls": [
        {
          "control_id": "NC1",
          "control_type": "negative_outcome",
          "rationale": "Selection and attrition pathways operate on all arms equally; the inactive-editor arm shares them.",
          "expected_result": "An H4 explanation predicts comparable baseline-health gradients in every arm, including controls.",
          "failure_implication": "Baseline gradients confined to the edit-bearing arm point away from selection and back toward treatment effects."
        }
      ],
      "outcome_interpretation": {
        "consistent_with_candidate": "Baseline-health gradient predicts response and the effect attenuates under paired analysis at adequate n.",
        "challenges_candidate": "Within-animal improvement independent of baseline health with symmetric attrition.",
        "supports_neither_or_mixed": "Attrition asymmetric but adjustment outcome inconclusive."
      },
      "human_review_status": "pending"
    },
    {
      "hypothesis_id": "H5",
      "candidate_status": "candidate",
      "assumptions": [
        "Off-target editing or DNA-damage responses can alter immune-cell composition or function through pathways distinct from the intended target."
      ],
      "boundary_conditions": [
        "Sorted-population purity and editing-assay sensitivity declared before analysis."
      ],
      "falsifier": {
        "prediction_id": "P5",
        "conditions": "On-target and off-target profiling with declared assay sensitivity.",
        "observable": "On-target editing fraction, off-target burden, p53-pathway signature, and their relation to restoration.",
        "incompatible_result": "Restoration tracks on-target editing fraction with minimal relevant off-target burden.",
        "assumption_failure_checks": [
          "Verify sorting purity, editing-assay sensitivity, and signature specificity before interpreting incompatibility."
        ]
      },
      "discriminating_tests": [
        {
          "test_id": "DT6",
          "rival_hypothesis_id": "H1",
          "focal_expected": "Restoration without detectable on-target editing, or tracking off-target burden.",
          "rival_expected": "Restoration tracking on-target editing fraction.",
          "indeterminate_result": "Both on-target and off-target edits present at interpretable fractions."
        }
      ],
      "nulls": [
        {
          "null_id": "N5",
          "statement": "Functional restoration does not correlate with on-target editing fraction across animals.",
          "analysis_id": "A5",
          "interpretation_limit": "Absence of detected off-targets is not absence of off-targets; correlation is not mechanism."
        }
      ],
      "controls": [
        {
          "control_id": "NC1",
          "control_type": "negative_outcome",
          "rationale": "The inactive-editor arm experiences the DNA-damage assay workflow without catalytic editing.",
          "expected_result": "No editing-dependent signature in the inactive-editor arm.",
          "failure_implication": "Signature detected in the inactive-editor arm implicates the assay or the editor package, not editing at any locus."
        }
      ],
      "outcome_interpretation": {
        "consistent_with_candidate": "Restoration present with on-target editing below detection, or tracking off-target burden or the p53 signature.",
        "challenges_candidate": "Restoration tracks on-target editing fraction with minimal off-target burden.",
        "supports_neither_or_mixed": "Both edit classes present at interpretable fractions."
      },
      "human_review_status": "pending"
    }
  ]
}

